def get_topic(self, arn: str) -> Topic:
    parsed_arn = parse_arn(arn)
    # First validate that the region in the ARN matches the region of this backend
    if parsed_arn.region != self.region_name:
        raise TopicNotFound("Topic not found in region")
    try:
        return sns_backends[parsed_arn.account][parsed_arn.region].topics[arn]
    except KeyError:
        raise TopicNotFound
